//! Checks `ReliableRandom` against `fixtures/rng.json`, generated by the TypeScript implementation.

use auto_composer::random::{ReliableRandom, Rng};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    state: i64,
    sequence: i64,
    u32: Vec<u32>,
}

fn load() -> Fixture {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/rng.json");
    let text = std::fs::read_to_string(path).expect("read fixtures/rng.json");
    serde_json::from_str(&text).expect("parse fixtures/rng.json")
}

#[test]
fn matches_reliable_random() {
    let fixture = load();
    assert!(!fixture.cases.is_empty());
    for c in fixture.cases {
        let mut r = ReliableRandom::new(c.state, c.sequence);
        let actual: Vec<u32> = c.u32.iter().map(|_| r.next_u32()).collect();
        assert_eq!(actual, c.u32, "state={} sequence={}", c.state, c.sequence);

        let mut f = ReliableRandom::new(c.state, c.sequence);
        for &v in &c.u32 {
            assert_eq!(f.random(), f64::from(v) / 2f64.powi(32));
        }
    }
}
